local HeadbandLoomMaker = {}
local PRODUCTS = {
    iron_headbandloom = { name = "Železni stati za kapice knjig", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni stati za kapice knjig za knjigoveze." },
    bronze_headbandloom = { name = "Bronast stati za kapice knjig", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast stati za kapice knjig za knjigoveze." },
    silver_headbandloom = { name = "Srebrn stati za kapice knjig", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn stati za kapice knjig za knjigoveze." },
    gilded_headbandloom = { name = "Pozlačen stati za kapice knjig", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen stati za kapice knjig za knjigoveze." },
    jewel_set_headbandloom = { name = "Draguljast stati za kapice knjig", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast stati za kapice knjig za knjigoveze." },
    royal_sovereign_headbandloom = { name = "Kraljevski suveren stati za kapice knjig", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren stati za kapice knjig z biseri za krono." },
}
local BUILDINGS = {
    headbandloom_workshop = { name = "Headbandloom delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    headbandloom_house = { name = "Headbandloom hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_headbandloom_atelier = { name = "Mojstrski headbandloom atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_headbandloom_palace = { name = "Suverena headbandloom palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
HeadbandLoomMaker.ironStock=12; HeadbandLoomMaker.bronzeStock=10; HeadbandLoomMaker.woodStock=16; HeadbandLoomMaker.leatherStock=10; HeadbandLoomMaker.silverStock=8; HeadbandLoomMaker.goldStock=6; HeadbandLoomMaker.jewelStock=4; HeadbandLoomMaker.pearlStock=4
HeadbandLoomMaker.productStock = {}; HeadbandLoomMaker.buildings = {}; HeadbandLoomMaker.maker = nil; HeadbandLoomMaker.activeMaking = {}; HeadbandLoomMaker.totalProducts = 0; HeadbandLoomMaker.dayTimer = 0
function HeadbandLoomMaker.init() HeadbandLoomMaker.ironStock=12; HeadbandLoomMaker.bronzeStock=10; HeadbandLoomMaker.woodStock=16; HeadbandLoomMaker.leatherStock=10; HeadbandLoomMaker.silverStock=8; HeadbandLoomMaker.goldStock=6; HeadbandLoomMaker.jewelStock=4; HeadbandLoomMaker.pearlStock=4; HeadbandLoomMaker.productStock={}; HeadbandLoomMaker.buildings={}; HeadbandLoomMaker.maker=nil; HeadbandLoomMaker.activeMaking={}; HeadbandLoomMaker.totalProducts=0; HeadbandLoomMaker.dayTimer=0; print("[HeadbandLoomMaker] Royal Headband Loom Maker System initialized (6 products, 4 buildings)") end
function HeadbandLoomMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HeadbandLoomMaker.maker={name=n or ("Statvar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Statvar najet: %s (spretnost: %d)",HeadbandLoomMaker.maker.name,s),"success") end; return true end
function HeadbandLoomMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HeadbandLoomMaker.build(id) local ok,e=HeadbandLoomMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HeadbandLoomMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HeadbandLoomMaker.getQualityBonus() local b=0; for _,bd in ipairs(HeadbandLoomMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HeadbandLoomMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HeadbandLoomMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HeadbandLoomMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HeadbandLoomMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HeadbandLoomMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HeadbandLoomMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HeadbandLoomMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HeadbandLoomMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HeadbandLoomMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HeadbandLoomMaker.buildings==0 then return false,"Potrebna statvena delavnica" end; if not HeadbandLoomMaker.maker then return false,"Potreben statvar" end; return true end
function HeadbandLoomMaker.make(pt,qty) qty=qty or 1; local ok,e=HeadbandLoomMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HeadbandLoomMaker.ironStock=HeadbandLoomMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HeadbandLoomMaker.bronzeStock=HeadbandLoomMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HeadbandLoomMaker.woodStock=HeadbandLoomMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HeadbandLoomMaker.leatherStock=HeadbandLoomMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HeadbandLoomMaker.silverStock=HeadbandLoomMaker.silverStock-d.silverCost*qty end; if d.goldCost then HeadbandLoomMaker.goldStock=HeadbandLoomMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HeadbandLoomMaker.jewelStock=HeadbandLoomMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HeadbandLoomMaker.pearlStock=HeadbandLoomMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HeadbandLoomMaker.maker then t=math.max(1,t-math.floor(HeadbandLoomMaker.maker.skill/13)) end; table.insert(HeadbandLoomMaker.activeMaking,{id="headbandloom_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HeadbandLoomMaker.completeMaking(m) local q=1.0+(HeadbandLoomMaker.getQualityBonus()/100); if HeadbandLoomMaker.maker then q=q+(HeadbandLoomMaker.maker.skill/140) end; q=math.min(2.5,q); HeadbandLoomMaker.productStock[m.productType]=(HeadbandLoomMaker.productStock[m.productType] or 0)+m.quantity; HeadbandLoomMaker.totalProducts=HeadbandLoomMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HeadbandLoomMaker.maker then HeadbandLoomMaker.maker.itemsMade=HeadbandLoomMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HeadbandLoomMaker.maker.skill=math.min(100,HeadbandLoomMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stati izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"headbandloom.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HeadbandLoomMaker.update(dt) if not _G.state then return end; HeadbandLoomMaker.dayTimer=HeadbandLoomMaker.dayTimer+dt; if HeadbandLoomMaker.dayTimer>=30 then HeadbandLoomMaker.dayTimer=0; for i=#HeadbandLoomMaker.activeMaking,1,-1 do local m=HeadbandLoomMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HeadbandLoomMaker.completeMaking(m); table.remove(HeadbandLoomMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HeadbandLoomMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HeadbandLoomMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HeadbandLoomMaker.getStats() return {ironStock=HeadbandLoomMaker.ironStock,bronzeStock=HeadbandLoomMaker.bronzeStock,woodStock=HeadbandLoomMaker.woodStock,leatherStock=HeadbandLoomMaker.leatherStock,silverStock=HeadbandLoomMaker.silverStock,goldStock=HeadbandLoomMaker.goldStock,jewelStock=HeadbandLoomMaker.jewelStock,pearlStock=HeadbandLoomMaker.pearlStock,productStock=HeadbandLoomMaker.productStock,numBuildings=#HeadbandLoomMaker.buildings,hasMaker=HeadbandLoomMaker.maker~=nil,makerName=HeadbandLoomMaker.maker and HeadbandLoomMaker.maker.name or "—",makerSkill=HeadbandLoomMaker.maker and HeadbandLoomMaker.maker.skill or 0,activeMaking=#HeadbandLoomMaker.activeMaking,totalProducts=HeadbandLoomMaker.totalProducts} end
return HeadbandLoomMaker
